import {key,categories,lessons,dayKey,addDays,dateGap,money,uid,initialState,balance,goalSaved,totalSaved,savingDays,xp,todayEntries,spent,validAmount,record,validateState,commit} from './core.mjs';

const $=s=>document.querySelector(s);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',wallet:'M3 7h17v13H3z M3 7V4h14v3 M16 12h5v4h-5z',history:'M6 3h12v18l-3-2-3 2-3-2-3 2Z M9 8h6 M9 12h6',learn:'m12 3 2.7 5.5 6 .9-4.4 4.3 1 6.1-5.3-2.9-5.3 2.9 1-6.1L2.3 9.4l6-.9Z',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',down:'M12 4v16 M6 14l6 6 6-6',calendar:'M5 5h14v16H5z M8 2v6 M16 2v6 M5 10h14',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',check:'m5 12 4 4L19 6',edit:'m4 16 12-12 4 4L8 20H4Z',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 11v5 M12 7v1'};
const icon=(id)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.wallet}"/></svg>`;
const pages=[['beranda','Beranda','home'],['celengan','Celengan impian','wallet'],['riwayat','Riwayat','history'],['belajar','Belajar yuk!','learn']];
let state=initialState(), broken=false, filter='all',hidden=false,toastTimer, lastDay=dayKey();
try { const raw=localStorage.getItem(key); if(raw) state=validateState(JSON.parse(raw)); } catch { broken=true; }
const page=()=>pages.some(p=>p[0]===location.hash.slice(1))?location.hash.slice(1):'beranda';
const dateText=d=>new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'long',year:'numeric'}).format(d);
const shortDate=d=>new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short'}).format(d);
const pct=g=>Math.min(100,Math.round(goalSaved(state,g.id)/g.target*100));
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function update(next,message){if(broken)throw Error('Pulihkan data terlebih dahulu.');state=commit(localStorage,next);render();if(message)toast(message);}
function perform(fn){try{fn();}catch(e){toast(e.message);}}
function navigate(name){location.hash=name;}
function header(title,subtitle,extra=''){return `<div class="page-heading"><div><p class="eyebrow">LANGKAH KECIL, IMPIAN BESAR</p><h1>${title}</h1><p class="subheading">${subtitle}</p></div>${extra}</div>`;}
function render(){
 const current=page(); const tabs=pages.map(([id,label,i])=>`<a href="#${id}" class="nav-item ${id===current?'active':''}" ${id===current?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('');
 $('#navigation').innerHTML=tabs;$('#mobile-navigation').innerHTML=tabs;$('#breadcrumb').textContent=pages.find(p=>p[0]===current)[1];$('#date-label').textContent=dateText(new Date());$('#profile-name').textContent=state.name;$('.avatar').textContent=state.name.slice(0,1).toUpperCase();
 if(broken){$('#main').innerHTML=header('Data belum bisa dibaca','Catatan lama tetap disimpan sampai kamu memilih memulihkannya.')+`<section class="card error-panel"><h2>Yuk, pulihkan catatanmu</h2><p>Browser tidak dapat membaca data lokal atau akses penyimpanan sedang dibatasi. Kamu bisa mengunduh data yang tersimpan, kemudian mencoba muat ulang. Reset hanya jika sudah siap menghapus data pada browser ini.</p><button class="primary" data-action="download-raw">Unduh data lama</button><button class="secondary" data-action="reload">Muat ulang</button><button class="secondary" data-action="reset">Reset data lokal</button></section>`;return;}
 const views={beranda:dashboard,celengan:goalsPage,riwayat:historyPage,belajar:learnPage};$('#main').innerHTML=views[current]();
}
const heroArt=`<svg class="hero-art" viewBox="0 0 230 230" aria-hidden="true"><ellipse cx="126" cy="207" rx="73" ry="10" fill="#075d49" opacity=".45"/><path d="M91 94 75 61l23 6 14-15 15 15 24-7-14 37Z" fill="#a7d7a0"/><path d="M89 92c-49 33-54 88-17 105 28 14 90 11 112-9 24-24-4-75-42-96Z" fill="#d1e7b6"/><path d="M124 101c36 18 65 63 41 91 26-9 33-35 11-66l-34-34Z" fill="#b6d99f"/><path d="m88 94 54-1" stroke="#549371" stroke-width="8" stroke-linecap="round"/><path d="M106 131h27m-27 14h27m-14-19v45m-12-26c35-2 30 23 2 17" fill="none" stroke="#58896c" stroke-width="5" stroke-linecap="round"/><circle cx="177" cy="65" r="23" fill="#f3d276"/><circle cx="177" cy="65" r="16" stroke="#dfb74c" stroke-width="2" fill="none"/><path d="M177 55v20m-5-16h7c7 0 7 8 0 8h-7" stroke="#bd963f" stroke-width="2" fill="none"/><circle cx="62" cy="157" r="17" fill="#f3d276"/><path d="m58 149 8 15m-12-9 13 3" stroke="#c6a64c" stroke-width="2"/><path d="m54 85 3 8 8 3-8 3-3 8-3-8-8-3 8-3Zm144 53 2 6 6 2-6 2-2 6-2-6-6-2 6-2Z" fill="#b6d5a5"/><circle cx="146" cy="32" r="3" fill="#f2da8e"/><circle cx="34" cy="130" r="2" fill="#b6d5a5"/></svg>`;
function dashboard(){
 const days=dateGap(state.nextPayday,dayKey());const payday=days>0?`Uang saku lagi <strong>${days} hari</strong>`:days===0?'Hari uang saku tiba!':'Jadwal uang saku sudah lewat';
 return header(`Halo, ${esc(state.name)}! <span class="wave">👋</span>`,'Siap bikin uang sakumu lebih berarti hari ini?',`<div class="small-status"><span></span> Ruang pribadimu</div>`)+`<div class="dashboard-grid"><div class="column">
 <section class="balance-card"><div class="balance-top">Saldo uang sakumu <button data-action="toggle-balance" aria-label="${hidden?'Tampilkan':'Sembunyikan'} saldo">${icon('eye')}</button></div><div class="balance-amount">${hidden?'Rp ••••••':money(balance(state))}</div><button class="payday-pill" data-action="settings">${icon('calendar')} ${payday}</button><button class="income-button" data-action="income">${icon('plus')} Uang saku masuk</button>${heroArt}</section>
 <div class="stats-row"><div class="stat-card"><span class="stat-icon orange">${icon('down')}</span><div><div class="stat-label">Pengeluaran hari ini</div><div class="stat-value">${hidden?'••••':money(spent(todayEntries(state)))}</div></div></div><div class="stat-card"><span class="stat-icon green">${icon('wallet')}</span><div><div class="stat-label">Berhasil disisihkan</div><div class="stat-value">${hidden?'••••':money(totalSaved(state))}</div></div></div></div>
 <section><div class="section-title"><div><h2>Catat cepat <small>⚡</small></h2><p>Habis jajan apa hari ini?</p></div><button class="subtle-link" data-action="expense">Nominal lain ${icon('plus')}</button></div><div class="quick-grid">${categories.map(c=>`<button class="quick-button" data-action="quick" data-id="${c.id}" aria-label="Catat ${esc(c.name)} ${money(c.amount)}"><span class="quick-emoji ${c.color}">${c.emoji}</span><span class="quick-name">${c.name}</span><span class="quick-amount">${money(c.amount)}</span></button>`).join('')}</div><div class="microcopy">${icon('info')} Sekali ketuk langsung tercatat sesuai nominal di atas.</div></section>
 ${chartCard()}
 <section class="card transactions-card"><div class="section-title"><h2>Catatan hari ini</h2><a class="subtle-link" href="#riwayat">Lihat semua ${icon('arrow')}</a></div>${transactionList(todayEntries(state).slice(0,5))}</section>
 </div><div class="column">${levelCard()}${goalCard(state.goals.find(g=>goalSaved(state,g.id)<g.target)||state.goals[0])}${challengeCard()}</div></div>`;
}
function levelCard(){const points=xp(state),level=1+Math.floor(points/100);return `<section class="card"><div class="level-header"><div class="level-emblem">🏅</div><div><div class="overline">TUMBUH BARENG SAKUPINTAR</div><h2>Pejuang Celengan <span style="color:#a99769">Lv. ${level}</span></h2><p>Setiap langkah kecilmu berharga.</p></div></div><div class="xp-labels"><strong>${points%100} / 100 XP</strong><span>Level ${level+1}</span></div><div class="progress amber" role="progressbar" aria-label="XP menuju level berikutnya" aria-valuenow="${points%100}" aria-valuemin="0" aria-valuemax="100"><span style="width:${points%100}%"></span></div><p class="level-foot"><span>✦</span> ${100-points%100} XP lagi. Kamu pasti bisa!</p></section>`;}
function goalCard(g){const saved=goalSaved(state,g.id),remaining=g.target-saved;return `<section class="card goal-card"><div class="goal-header"><h2>Celengan impian</h2><span class="tiny-tag">MY LITTLE DREAM</span></div><div class="goal-visual"><span class="float-star">✦</span><span class="goal-emoji">${esc(g.emoji)}</span><span class="goal-sticker">${remaining<=0?'Impian tercapai!':'Pelan-pelan, jadi nyata ✨'}</span><span class="float-star">✦</span></div><h3 class="goal-name">${esc(g.name)}</h3><p class="goal-target">Target ${money(g.target)}</p><div class="goal-labels"><strong>${hidden?'••••':money(saved)}</strong><span>${pct(g)}%</span></div><div class="progress" role="progressbar" aria-label="Progres ${esc(g.name)}" aria-valuenow="${pct(g)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${pct(g)}%"></span></div><div class="goal-foot"><span>${remaining<=0?'Semua langkahmu terbayar.':'Sedikit lagi, semangat!'}</span><span>${remaining<=0?'🎉':`Kurang ${money(remaining)}`}</span></div>${remaining>0?`<div class="card-actions"><button class="save-button" data-action="save-instant" data-id="${g.id}">+ Isi ${money(Math.min(5000,remaining))}</button><button class="icon-button" data-action="save-custom" data-id="${g.id}" aria-label="Isi tabungan nominal lain">${icon('edit')}</button></div>`:'<div class="goal-achieved">✓ Impianmu berhasil terkumpul!</div>'}</section>`;}
function challengeCard(){const days=savingDays(state).size;return `<section class="card challenge"><div class="challenge-top"><span>MISI KECILMU</span><span>✦ KEBIASAAN BAIK</span></div><h3>Jadi teman celengan 🐷</h3><p>Menabung pada 3 tanggal berbeda.<br>Sedikit pun tetap berarti!</p><span class="challenge-medal">${days>=3?'🏆':'🎖️'}</span><div class="challenge-bottom"><strong>${Math.min(days,3)} dari 3 hari</strong><span>${days>=3?'Lencana terbuka ✓':'Lencana menantimu'}</span></div><div class="progress amber" style="margin-top:10px"><span style="width:${Math.min(days/3*100,100)}%"></span></div></section>`;}
function transactionList(entries){if(!entries.length)return `<div class="empty-state"><span class="empty-icon">📝</span><h3>Masih bersih, nih!</h3><p>Mulai dengan mencatat uang saku masuk.<br>Perjalanan pintarmu dimulai dari sini.</p></div>`;return `<div class="transactions">${entries.map(e=>`<div class="transaction"><span class="transaction-icon">${esc(e.emoji)}</span><div class="transaction-info"><h3>${esc(e.label)}</h3><p>${dayKey(new Date(e.date))===dayKey()?'Hari ini':shortDate(new Date(e.date))} · ${new Date(e.date).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})} · ${e.kind==='saving'?'Ke celengan':e.kind==='income'?'Uang masuk':'Pengeluaran'}</p></div><span class="transaction-amount ${e.kind}">${e.kind==='income'?'+':'−'} ${hidden?'••••':money(e.amount)}</span></div>`).join('')}</div>`;}
function chartCard(){const days=Array.from({length:7},(_,i)=>addDays(dayKey(),i-6));const vals=days.map(d=>({date:d,out:spent(state.entries.filter(e=>dayKey(new Date(e.date))===d)),save:state.entries.filter(e=>e.kind==='saving'&&dayKey(new Date(e.date))===d).reduce((a,e)=>a+e.amount,0)}));const max=Math.max(10000,...vals.flatMap(v=>[v.out,v.save]));const points=field=>vals.map((v,i)=>`${45+i*62},${104-v[field]/max*82}`).join(' ');const labels=[0,.5,1].map(f=>`<line x1="42" y1="${104-f*82}" x2="418" y2="${104-f*82}" stroke="#edf2e9" stroke-dasharray="3 4"/><text x="0" y="${107-f*82}">${Math.round(max*f/1000)}rb</text>`).join('');return `<section class="card chart-card"><div class="chart-header"><h2>Jejak uang sakumu</h2><span class="tiny-tag">7 HARI TERAKHIR</span></div><div class="chart-legend"><span><i></i> Ditabung</span><span><i></i> Pengeluaran</span></div><svg class="chart" viewBox="0 0 440 140" role="img" aria-label="Grafik pengeluaran dan tabungan tujuh hari terakhir">${labels}<polyline points="${points('save')}" fill="none" stroke="#72a986" stroke-width="2.5" stroke-linejoin="round"/><polyline points="${points('out')}" fill="none" stroke="#e9c572" stroke-width="2.5" stroke-linejoin="round"/>${vals.map((v,i)=>`<circle cx="${45+i*62}" cy="${104-v.save/max*82}" r="3" fill="#72a986" stroke="white" stroke-width="1.5"/><text x="${45+i*62}" y="132" text-anchor="middle">${new Date(`${v.date}T12:00:00`).toLocaleDateString('id-ID',{weekday:'short'})}</text>`).join('')}</svg><p class="chart-note">${state.entries.length?'Catatan kecil membantu kamu melihat kebiasaanmu.':'Grafik akan tumbuh bersama catatan uang sakumu.'}</p></section>`;}
function goalsPage(){return header('Impianmu layak diperjuangkan ✨','Satu celengan, satu langkah lebih dekat.',`<button class="primary" data-action="new-goal">${icon('plus')} Impian baru</button>`)+`<p class="goal-subtitle">Total ${money(totalSaved(state))} sudah kamu sisihkan. Tabungan terpisah dari saldo jajan, jadi tidak terhitung dua kali.</p><div class="goal-grid">${state.goals.map(goalCard).join('')}</div>`;}
function historyPage(){const entries=state.entries.filter(e=>filter==='all'||e.kind===filter);return header('Setiap receh punya cerita 📝','Kenali jejak uangmu, temukan kebiasaan baikmu.',`<button class="primary" data-action="export">Unduh catatan</button>`)+`<div class="history-summary"><div class="card"><p>Uang saku masuk</p><strong>${money(state.entries.filter(e=>e.kind==='income').reduce((a,e)=>a+e.amount,0))}</strong></div><div class="card"><p>Sudah digunakan</p><strong>${money(spent(state.entries))}</strong></div><div class="card"><p>Aman di celengan</p><strong>${money(totalSaved(state))}</strong></div></div><div class="filters">${[['all','Semua'],['income','Uang masuk'],['expense','Pengeluaran'],['saving','Tabungan']].map(([id,label])=>`<button class="filter ${filter===id?'active':''}" data-action="filter" data-id="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><section class="card">${transactionList(entries)}</section>`;}
function learnPage(){const days=savingDays(state).size;return header('Pintar uang, pintar memilih 🌟','Belajar sedikit hari ini, lebih percaya diri besok.')+`<section class="learn-intro"><span class="big-star">🌟</span><div><h2>Kamu sudah mengumpulkan ${xp(state)} XP!</h2><p>+25 XP pada setiap tanggal menabung. +10 XP untuk setiap kuis baru yang selesai.<br>Bukan soal paling banyak uangnya, tapi kebiasaan baiknya.</p></div></section><div class="badge-row"><span class="badge ${totalSaved(state)>0?'earned':''}">${totalSaved(state)>0?'🏅':'🔒'} Langkah pertama</span><span class="badge ${days>=3?'earned':''}">${days>=3?'🏆':'🔒'} Teman celengan · ${Math.min(days,3)}/3 hari</span><span class="badge ${state.goals.some(g=>pct(g)>=100)?'earned':''}">${state.goals.some(g=>pct(g)>=100)?'🎯':'🔒'} Impian tercapai</span></div><div class="lesson-grid">${lessons.map(l=>`<article class="card lesson-card"><div class="lesson-emoji">${l.emoji}</div><span class="tiny-tag">BELAJAR 1 MENIT · ${state.completed.includes(l.id)?'SELESAI ✓':'+10 XP'}</span><h2 style="margin-top:14px">${l.title}</h2><p>${l.subtitle}</p><button class="save-button" data-action="lesson" data-id="${l.id}">${state.completed.includes(l.id)?'Baca lagi':'Mulai belajar'} →</button></article>`).join('')}</div>`;}
function showDialog(title,description,content){$('#dialog-content').innerHTML=`<div class="dialog-inner"><div class="dialog-header"><h2>${title}</h2><button class="dialog-close" data-action="close" aria-label="Tutup">×</button></div><p class="dialog-description">${description}</p>${content}</div>`;$('#dialog').showModal();document.body.classList.add('body-hidden');}
const footer=label=>`<div class="form-error" id="form-error" role="alert"></div><div class="dialog-footer"><button type="button" class="secondary" data-action="close">Batal</button><button type="submit" class="primary">${label}</button></div>`;
function amountDialog(kind,g){const isSave=kind==='saving',income=kind==='income';const remain=isSave?g.target-goalSaved(state,g.id):null;showDialog(income?'Uang saku masuk 💸':isSave?'Isi celengan impian 🐷':'Catat pengeluaran ✍️',income?'Catat uang yang benar-benar kamu terima. Saldo tidak bertambah otomatis.':isSave?`${esc(g.name)} · Masih perlu ${money(remain)}. Saldo jajan ${money(balance(state))}.`:'Nominal berbeda? Catat sesuai uang yang kamu keluarkan.',`<form id="amount-form" data-kind="${kind}" data-goal="${g?.id||''}">${kind==='expense'?`<div class="form-group"><label for="category">Kategori</label><select id="category" name="category">${categories.map(c=>`<option value="${c.id}">${c.emoji} ${c.name}</option>`).join('')}<option value="lain">✍️ Lainnya</option></select></div>`:''}<div class="form-group"><label for="amount">Nominal rupiah</label><input id="amount" name="amount" type="number" min="1" max="100000000" step="1" inputmode="numeric" placeholder="Contoh: 10000" required autofocus></div><div class="preset-row">${(income?[20000,50000,100000]:[2000,5000,10000]).map(n=>`<button type="button" data-action="preset" data-value="${n}">${money(n)}</button>`).join('')}</div>${footer(isSave?'Sisihkan sekarang':'Simpan catatan')}</form>`);}
function newGoalDialog(){showDialog('Impian baru ✨','Apa yang lagi ingin kamu wujudkan? Mulai dari target yang masuk akal.',`<form id="goal-form"><div class="form-group"><label for="goal-name">Nama impian</label><input id="goal-name" name="name" maxlength="50" placeholder="Misalnya: Raket badminton" required autofocus></div><div class="form-row"><div class="form-group"><label for="goal-emoji">Ikon impian</label><select id="goal-emoji" name="emoji"><option>👟</option><option>🎧</option><option>📚</option><option>🏸</option><option>🚲</option><option>🎮</option><option>🎒</option></select></div><div class="form-group"><label for="goal-target">Target rupiah</label><input id="goal-target" name="target" type="number" min="1" max="100000000" step="1" inputmode="numeric" placeholder="250000" required></div></div>${footer('Buat celengan')}</form>`);}
function settingsDialog(){showDialog('Ruang pribadimu 🌱','Atur nama dan jadwal uang saku sesuai kebiasaanmu.',`<form id="settings-form"><div class="form-group"><label for="name">Nama panggilan</label><input id="name" name="name" value="${esc(state.name)}" maxlength="30" required></div><div class="form-row"><div class="form-group"><label for="interval">Uang saku</label><select id="interval" name="interval"><option value="7" ${state.interval===7?'selected':''}>Mingguan</option><option value="1" ${state.interval===1?'selected':''}>Harian</option></select></div><div class="form-group"><label for="payday">Tanggal berikutnya</label><input id="payday" name="payday" type="date" value="${state.nextPayday<dayKey()?dayKey():state.nextPayday}" min="${dayKey()}" required></div></div>${footer('Simpan pengaturan')}</form><p class="privacy-note">🔒 Catatan tersimpan di browser ini, tanpa akun aplikasi. Gunakan cadangan agar catatanmu tidak hilang saat data browser dibersihkan.</p><div class="settings-tools"><button class="secondary" data-action="export">Unduh cadangan</button><button class="secondary" data-action="import">Pulihkan cadangan</button><button class="secondary" data-action="reset">Reset data lokal</button>${state.entries.length===0?'<button class="secondary" data-action="demo">Coba data contoh</button>':''}</div><p class="data-tools-message">Data contoh hanya untuk menjelajahi fitur. Saldo bukan uang sungguhan.</p>`);}
function lessonDialog(id){const l=lessons.find(l=>l.id===id);showDialog(`${l.emoji} ${l.title}`,l.text,`<h3 style="font-size:14px;line-height:1.8">${l.question}</h3><div class="quiz-options">${l.answers.map((a,i)=>`<button data-action="answer" data-id="${id}" data-value="${i}">${esc(a)}</button>`).join('')}</div><div id="quiz-feedback" role="status"></div>`);}
function download(text,name){const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function closeDialog(){$('#dialog').close();}
function demo(){if(state.entries.length)throw Error('Data contoh hanya tersedia saat catatanmu kosong.');let s=initialState();s.name=state.name;for(let i=6;i>=0;i--){const d=new Date(`${addDays(dayKey(),-i)}T12:00:00`);if(i===6)s=record(s,{kind:'income',label:'Uang saku contoh',emoji:'💸',amount:100000},d);s=record(s,{kind:'expense',label:i%2?'Kantin':'Ongkos',emoji:i%2?'🍜':'🚌',category:i%2?'kantin':'ongkos',amount:i%2?7000:5000},d);if(i%2===0)s=record(s,{kind:'saving',label:'Sepatu futsal baru',emoji:'🐷',amount:5000,goalId:'futsal'},d);}update(s,'Data contoh dimuat. Bisa direset melalui pengaturan.');closeDialog();}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const {action,id,value}=b.dataset;
 if(broken&&!['download-raw','reload','reset','confirm-reset','close'].includes(action)){toast('Pulihkan data dahulu, ya.');return;}
 perform(()=>{switch(action){
 case 'go-goals':navigate('celengan');break;
 case 'income':amountDialog('income');break;
 case 'expense':amountDialog('expense');break;
 case 'settings':settingsDialog();break;
 case 'close':closeDialog();break;
 case 'toggle-balance':hidden=!hidden;render();break;
 case 'quick':{const cat=categories.find(c=>c.id===id);update(record(state,{kind:'expense',label:cat.name,emoji:cat.emoji,category:cat.id,amount:cat.amount}),`${cat.emoji} ${cat.name} ${money(cat.amount)} tercatat.`);break;}
 case 'save-instant':{const g=state.goals.find(g=>g.id===id);update(record(state,{kind:'saving',label:g.name,emoji:'🐷',amount:Math.min(5000,g.target-goalSaved(state,g.id)),goalId:id}),'🐷 Tabungan bertambah. Selangkah lebih dekat!');break;}
 case 'save-custom':amountDialog('saving',state.goals.find(g=>g.id===id));break;
 case 'new-goal':newGoalDialog();break;
 case 'preset':$('#amount').value=value;$('#amount').focus();break;
 case 'filter':filter=id;render();break;
 case 'lesson':lessonDialog(id);break;
 case 'answer':{const l=lessons.find(l=>l.id===id),correct=Number(value)===l.correct;if(correct){const first=!state.completed.includes(id);if(first)update({...state,completed:[...state.completed,id]},'🌟 Kuis selesai! +10 XP untukmu.');$('#quiz-feedback').innerHTML=`<p class="quiz-result">${l.why} ${first?'+10 XP!':'Kamu sudah mendapat XP kuis ini sebelumnya.'}</p>`;document.querySelectorAll('.quiz-options button').forEach(b=>b.disabled=true);}else $('#quiz-feedback').innerHTML='<p class="quiz-result">Belum tepat. Baca tipsnya lagi dan coba jawaban lain, ya!</p>';break;}
 case 'export':download(JSON.stringify(state,null,2),`sakupintar-${dayKey()}.json`);toast('Cadangan berhasil disiapkan.');break;
 case 'download-raw':download(localStorage.getItem(key)||'{}',`sakupintar-pemulihan-${dayKey()}.json`);break;
 case 'reload':location.reload();break;
 case 'demo':showDialog('Coba dengan data contoh? 🧪','Ini akan mengisi saldo dan riwayat contoh, bukan uang sungguhan. Data contoh bisa dihapus melalui reset data lokal.',`<button class="primary" data-action="confirm-demo">Ya, coba data contoh</button>`);break;
 case 'confirm-demo':demo();break;
 case 'reset':showDialog('Reset catatan lokal?','Semua transaksi, celengan, dan XP di browser ini akan dihapus. Unduh cadangan terlebih dahulu jika diperlukan.',`<button class="primary" data-action="confirm-reset">Hapus data dan mulai ulang</button>`);break;
 case 'confirm-reset':{const fresh=initialState();state=commit(localStorage,fresh);broken=false;closeDialog();render();toast('Catatan baru siap dimulai.');break;}
 case 'import':{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{if(!input.files[0])return;if(input.files[0].size>5000000)throw Error('Ukuran cadangan maksimal 5 MB.');const restored=validateState(JSON.parse(await input.files[0].text()));showDialog('Pulihkan cadangan?','Cadangan ini akan mengganti seluruh catatan pada browser ini. Unduh cadangan saat ini sebelum melanjutkan.',`<button class="primary" id="confirm-import">Pulihkan ${restored.entries.length} catatan</button>`);$('#confirm-import').onclick=()=>perform(()=>{update(restored,'Cadangan berhasil dipulihkan.');closeDialog();});}catch(e){toast(e.message);}});input.click();break;}
 }});
});
document.addEventListener('submit',event=>{if(!event.target.matches('#amount-form,#goal-form,#settings-form'))return;event.preventDefault();const form=event.target,data=new FormData(form);try{
 if(form.id==='amount-form'){const kind=form.dataset.kind,amount=validAmount(data.get('amount')),cat=categories.find(c=>c.id===data.get('category')),goal=state.goals.find(g=>g.id===form.dataset.goal);update(record(state,{kind,amount,label:kind==='saving'?goal.name:kind==='income'?'Uang saku':cat?.name||'Pengeluaran lain',emoji:kind==='saving'?'🐷':kind==='income'?'💸':cat?.emoji||'✍️',category:cat?.id||'lain',goalId:goal?.id}),'✓ Catatanmu berhasil disimpan.');}
 if(form.id==='goal-form'){const name=String(data.get('name')).trim();if(!name||name.length>50)throw Error('Nama impian harus 1–50 karakter.');update({...state,goals:[...state.goals,{id:uid(),name,emoji:data.get('emoji'),target:validAmount(data.get('target'))}]},'✨ Impian baru siap diperjuangkan!');}
 if(form.id==='settings-form'){const name=String(data.get('name')).trim(),date=String(data.get('payday'));if(!name||name.length>30)throw Error('Isi nama panggilan 1–30 karakter.');if(date<dayKey())throw Error('Pilih tanggal hari ini atau sesudahnya.');update({...state,name,nextPayday:date,interval:Number(data.get('interval'))},'Pengaturan disimpan.');}
 closeDialog();
 }catch(e){$('#form-error').textContent=e.message;}
});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
$('#dialog').addEventListener('close',()=>document.body.classList.remove('body-hidden'));
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('storage',e=>{if(e.key!==key)return;try{state=e.newValue?validateState(JSON.parse(e.newValue)):initialState();broken=false;}catch{broken=true;}render();});
setInterval(()=>{if(lastDay!==dayKey()){lastDay=dayKey();render();}},30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});
render();
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
